// FormatAgoJustNow is format.ago.just_now: "just now".
func FormatAgoJustNow() Text {
	return Text{m: &messages[0]}
}

// FormatAgoMinutes is format.ago.minutes: "{m}m ago".
func FormatAgoMinutes(m int) Text {
	return Text{m: &messages[1], args: []Arg{{"m", catalog.Int, m}}}
}

// FormatAgoHours is format.ago.hours: "{h}h ago".
func FormatAgoHours(h int) Text {
	return Text{m: &messages[2], args: []Arg{{"h", catalog.Int, h}}}
}

// FormatAgoDays is format.ago.days: "{d}d ago".
func FormatAgoDays(d int) Text {
	return Text{m: &messages[3], args: []Arg{{"d", catalog.Int, d}}}
}

